import React from 'react';
import {
  Box,
  Container
} from '@mui/material';
import Slider from 'react-slick';
import "slick-carousel/slick/slick.css"; 
import "slick-carousel/slick/slick-theme.css";

const App = () => {
  const settings = {
    dots: true,
    infinite: true,
    speed: 500,
    slidesToShow: 1,
    slidesToScroll: 1,
    autoplay: true,
    autoplaySpeed: 3000,
  };

  return (
    <>
      

      {/* Carousel */}
      <Box sx={{ bgcolor: '#f6f8ff', py: 5 }}>
        <Container maxWidth="lg">
          <Slider {...settings}>
            <Box>
              <img
                src="./assets/images/banner1.webp"
                alt="Banner 1"
                style={{ width: '100%', borderRadius: '10px' }}
              />
            </Box>
            <Box>
              <img
                src="./assets/images/banner2.webp"
                alt="Banner 2"
                style={{ width: '100%', borderRadius: '10px' }}
              />
            </Box>
            <Box>
              <img
                src="./assets/images/banner3.webp"
                alt="Banner 3"
                style={{ width: '100%', borderRadius: '10px' }}
              />
            </Box>
          </Slider>
        </Container>
      </Box>

      

     
    </>
  );
};

export default App;
